2	import {
3	  Animated,
4	  Pressable,
5	  StyleProp,
6	  StyleSheet,
7	  View,
8	  ViewStyle,
9	} from 'react-native';
10	import { useTheme } from '../theme';
11	import { haptic } from '../utils/haptics';
12	import { Text } from './Text';
13	import { motion, radius, spacing } from './tokens';
14	
15	export type ButtonVariant = 'filled' | 'tonal' | 'outlined' | 'text' | 'danger';
16	export type ButtonSize = 'sm' | 'md' | 'lg' | 'xl';
17	
18	type Props = {
19	  label: string;
20	  onPress: () => void;
21	  variant?: ButtonVariant;
22	  size?: ButtonSize;
23	  leadingIcon?: React.ReactNode;
24	  trailingIcon?: React.ReactNode;
25	  disabled?: boolean;
26	  loading?: boolean;
27	  fullWidth?: boolean;
28	  style?: StyleProp<ViewStyle>;
29	  testID?: string;
30	};
31	
32	type Tokens = { bg: string; fg: string; border: string; pressedBg: string };
33	
34	const SIZES: Record<
35	  ButtonSize,
36	  { h: number; px: number; gap: number; variant: 'labelLarge' | 'titleMedium' | 'titleLarge' | 'headlineSmall' }
37	> = {
38	  sm: { h: 40, px: spacing.lg, gap: spacing.sm, variant: 'labelLarge' },
39	  md: { h: 52, px: spacing.xl, gap: spacing.sm, variant: 'titleMedium' },
40	  lg: { h: 64, px: spacing.xl, gap: spacing.md, variant: 'titleLarge' },
41	  xl: { h: 88, px: spacing.xl, gap: spacing.md, variant: 'headlineSmall' },
42	};
43	
44	/**
45	 * Darken a hex color by a fixed amount. Used to derive a pressed-state
46	 * shade from the theme's primary so we don't hardcode a color that only
47	 * looks right under one brand.
48	 */
49	function darken(hex: string, amount = 0.12): string {
50	  const m = /^#?([0-9a-f]{6})$/i.exec(hex);
51	  if (!m) return hex;
52	  const num = parseInt(m[1], 16);
53	  const r = Math.max(0, Math.round(((num >> 16) & 0xff) * (1 - amount)));
54	  const g = Math.max(0, Math.round(((num >> 8) & 0xff) * (1 - amount)));
55	  const b = Math.max(0, Math.round((num & 0xff) * (1 - amount)));
56	  return `#${((r << 16) | (g << 8) | b).toString(16).padStart(6, '0')}`;
57	}
58	
59	export function Button({
60	  label,
61	  onPress,
62	  variant = 'filled',
63	  size = 'md',
64	  leadingIcon,
65	  trailingIcon,
66	  disabled,
67	  loading,
68	  fullWidth,
69	  style,
70	  testID,
71	}: Props) {
72	  const { palette } = useTheme();
73	  const scale = useRef(new Animated.Value(1)).current;
74	  const s = SIZES[size];
75	  const isDisabled = !!disabled || !!loading;
76	
77	  const t: Tokens = (() => {
78	    if (isDisabled) {
79	      return {
80	        bg: palette.surfaceContainerHighest,
81	        fg: palette.onSurfaceVariant,
82	        border: 'transparent',
83	        pressedBg: palette.surfaceContainerHighest,
84	      };
85	    }
86	    switch (variant) {
87	      case 'filled':
88	        return {
89	          bg: palette.primary,
90	          fg: palette.onPrimary,
91	          border: 'transparent',
